/* Hacker News DNA — web-1.0 artifact: beige, Verdana, tables, zero ornament */
.theme-hackernews-dna {
  --bg: oklch(0.971 0.009 106.6);
  --surface: oklch(0.971 0.009 106.6);
  --surface-2: oklch(0.946 0.013 106.7);
  --fg: oklch(0.000 0 0);
  --fg-muted: oklch(0.607 0 0);
  --accent: oklch(0.680 0.204 43.5);
  --accent-fg: oklch(1.000 0 0);
  --accent-2: oklch(0.607 0 0);
  --line: oklch(0.898 0 0);
  --success: oklch(0.512 0.107 144.2);
  --warning: oklch(0.552 0.077 79.7);
  --danger: oklch(0.522 0.134 24.0);
  --radius: 0px;
  --radius-sm: 0px;
  --radius-lg: 0px;
  --radius-pill: 0px;
  --shadow-1: none;
  --shadow-2: none;
  --shadow-3: none;
  --glow: 0 0 0 1px var(--accent);
  --border-width: 1px;
  --blur-amount: 0px;
  --font-display: Verdana, Geneva, sans-serif;
  --font-body: Verdana, Geneva, sans-serif;
  --font-mono: "Courier New", monospace;
  --tracking-display: 0em;
  --label-transform: none;
  --label-tracking: 0.02em;

  background-color: var(--bg);
  color: var(--fg);
  font-family: var(--font-body);
}

.theme-hackernews-dna h1,
.theme-hackernews-dna h2,
.theme-hackernews-dna h3 {
  font-family: var(--font-display);
  letter-spacing: var(--tracking-display);
}

/* signature */
.theme-hackernews-dna { border-top: 4px solid var(--accent); font-size: 14px; }
.theme-hackernews-dna * { border-radius: 0 !important; box-shadow: none !important; transition: none !important; }
.theme-hackernews-dna h1 { font-size: 1.5rem !important; font-weight: 700; }
.theme-hackernews-dna .label-caps { text-transform: none; letter-spacing: 0; }

/* depth */
.theme-hackernews-dna thead th { background: var(--accent); color: var(--accent-fg); font-weight: 700; font-size: 13px; padding: 2px 8px; border: none; text-align: left; }
.theme-hackernews-dna td { font-size: 13px; padding: 3px 8px; border: none; }
.theme-hackernews-dna tbody tr:nth-child(even) td { background: var(--surface-2); }
.theme-hackernews-dna tbody tr:hover td { background: oklch(0.922 0.020 106.7); }
.theme-hackernews-dna input, .theme-hackernews-dna textarea, .theme-hackernews-dna select { font-family: var(--font-body); font-size: 13px; background: oklch(1 0 0); border: 1px solid var(--fg-muted); padding: 2px 4px; }
.theme-hackernews-dna input:focus-visible, .theme-hackernews-dna textarea:focus-visible, .theme-hackernews-dna select:focus-visible { outline: 1px solid var(--fg); outline-offset: 0; border-color: var(--fg); }
.theme-hackernews-dna kbd { font-family: var(--font-mono); font-size: 12px; background: var(--surface-2); border: 1px solid var(--fg-muted); padding: 0 3px; }
.theme-hackernews-dna a { color: var(--fg); text-decoration: none; }
.theme-hackernews-dna a:hover { text-decoration: underline; }
.theme-hackernews-dna a:visited { color: var(--fg-muted); }
.theme-hackernews-dna ::selection { background: oklch(0.696 0.204 43.5 / 30%); color: var(--fg); }
.theme-hackernews-dna ::-webkit-scrollbar { width: 12px; }
.theme-hackernews-dna ::-webkit-scrollbar-track { background: var(--surface-2); }
.theme-hackernews-dna ::-webkit-scrollbar-thumb { background: oklch(0.75 0 0); border: 2px solid var(--surface-2); }
.theme-hackernews-dna .label-caps { color: var(--fg-muted); font-size: 11px; }
.theme-hackernews-dna .themed-border { border: 1px solid var(--line); background: var(--surface-2); }
.theme-hackernews-dna ul { list-style: none; }
.theme-hackernews-dna ul li::before { content: "▲ "; color: oklch(0.75 0.02 106); font-size: 10px; }
.theme-hackernews-dna button { font-family: var(--font-body); font-size: 13px; background: var(--surface-2); border: 1px solid var(--fg-muted); color: var(--fg); }
.theme-hackernews-dna hr { border: none; border-top: 1px solid var(--line); }

/* status chips: light tinted tags need dark ink (web-1.0 flat tags) */
.theme-hackernews-dna span.bg-danger { color: oklch(0.45 0.14 25); }
.theme-hackernews-dna span.bg-success { color: oklch(0.38 0.1 144); }
.theme-hackernews-dna span.bg-accent { color: oklch(0.5 0.17 43); }
.theme-hackernews-dna nav span.bg-accent { color: var(--accent-fg); }

/* alt mode: terminal-orange dark — beige inverted, top bar still #ff6600 */
.theme-hackernews-dna.alt-mode {
  --bg: oklch(0.185 0.012 106.6);
  --surface: oklch(0.185 0.012 106.6);
  --surface-2: oklch(0.24 0.012 106.6);
  --fg: oklch(0.90 0.010 100);
  --fg-muted: oklch(0.64 0.010 100);
  --line: oklch(0.34 0.010 106.6);
  --shadow-1: none;
  --shadow-2: none;
  --shadow-3: none;
}
.theme-hackernews-dna.alt-mode tbody tr:hover td { background: oklch(0.28 0.014 106.6); }
.theme-hackernews-dna.alt-mode span.bg-danger { color: oklch(0.82 0.09 25); }
.theme-hackernews-dna.alt-mode span.bg-success { color: oklch(0.82 0.09 144); }
.theme-hackernews-dna.alt-mode span.bg-accent { color: oklch(0.83 0.11 55); }
.theme-hackernews-dna.alt-mode span.bg-warning { color: oklch(0.84 0.09 85); }
.theme-hackernews-dna.alt-mode nav span.bg-accent { color: var(--accent-fg); }
.theme-hackernews-dna.alt-mode input, .theme-hackernews-dna.alt-mode textarea, .theme-hackernews-dna.alt-mode select { background: oklch(0.14 0.01 106.6); color: var(--fg); border-color: var(--fg-muted); }
.theme-hackernews-dna.alt-mode a { color: var(--fg); }
.theme-hackernews-dna.alt-mode a:visited { color: var(--fg-muted); }
.theme-hackernews-dna.alt-mode ::selection { background: oklch(0.696 0.204 43.5 / 45%); color: oklch(0.97 0.005 100); }
.theme-hackernews-dna.alt-mode ::-webkit-scrollbar-thumb { background: oklch(0.42 0.01 106.6); }
.theme-hackernews-dna.alt-mode kbd { background: var(--surface-2); border-color: var(--fg-muted); }

/* Bridge shadcn semantic variables to the theme tokens so stock shadcn/ui
   components are skinned by the theme. Scope-safe: applies inside the theme
   class only. */
[class*="theme-"] {
  --background: var(--bg);
  --foreground: var(--fg);
  --card: var(--surface);
  --card-foreground: var(--fg);
  --popover: var(--surface);
  --popover-foreground: var(--fg);
  --primary: var(--accent);
  --primary-foreground: var(--accent-fg);
  --secondary: var(--surface-2);
  --secondary-foreground: var(--fg);
  --muted: var(--surface-2);
  --muted-foreground: var(--fg-muted);
  --accent-foreground: var(--accent-fg);
  --border: var(--line);
  --input: var(--line);
  --ring: var(--accent);
  --destructive: var(--danger);
  --destructive-foreground: var(--accent-fg);

  /* Full app surface: sidebar, charts, app-level font + shadow + tracking vars.
     These are what real products (shadcn full kit, RootCX-style UI kits) consume —
     without them a retrofit looks half-themed. */
  --sidebar: var(--surface-2);
  --sidebar-foreground: var(--fg);
  --sidebar-primary: var(--accent);
  --sidebar-primary-foreground: var(--accent-fg);
  --sidebar-accent: color-mix(in oklab, var(--accent) 12%, var(--surface-2));
  --sidebar-accent-foreground: var(--fg);
  --sidebar-border: var(--line);
  --sidebar-ring: var(--accent);

  --chart-1: var(--accent);
  --chart-2: var(--accent-2);
  --chart-3: var(--success);
  --chart-4: var(--warning);
  --chart-5: var(--danger);

  --font-sans: var(--font-body);
  --font-heading: var(--font-display);
  --font-serif: var(--font-display);

  --shadow-2xs: var(--shadow-1);
  --shadow-xs: var(--shadow-1);
  --shadow-sm: var(--shadow-1);
  --shadow: var(--shadow-2);
  --shadow-md: var(--shadow-2);
  --shadow-lg: var(--shadow-3);
  --shadow-xl: var(--shadow-3);
  --shadow-2xl: var(--shadow-3);

  --tracking-normal: 0em;
}

/* Base experience: make the theme own the canvas and native elements even in
   apps that never adopted semantic classes. Scoped to the theme wrapper. */
[class*="theme-"] {
  background-color: var(--bg);
  color: var(--fg);
  font-family: var(--font-body);
}
[class*="theme-"] :is(h1, h2, h3, h4) { font-family: var(--font-display); }
[class*="theme-"] :is(code, pre, kbd, samp) { font-family: var(--font-mono); }
[class*="theme-"] ::selection { background: color-mix(in oklab, var(--accent) 30%, transparent); }

/* OPT-IN HARD MODE — add "sf-enforce" beside the theme class when the host app
   bakes font/shadow/radius literals into its compiled utilities (a var bridge
   cannot beat a literal). Targeted !important, fonts and surfaces only. */
[class*="theme-"].sf-enforce { font-family: var(--font-body) !important; }
[class*="theme-"].sf-enforce :is(h1, h2, h3, h4, [class*="font-heading"], [class*="text-2xl"], [class*="text-3xl"], [class*="text-4xl"], [class*="text-5xl"]) {
  font-family: var(--font-display) !important;
  letter-spacing: var(--tracking-display) !important;
}
[class*="theme-"].sf-enforce :is(button, [role="button"]) { font-family: var(--font-ui, var(--font-body)) !important; }
[class*="theme-"].sf-enforce :is(code, pre, kbd) { font-family: var(--font-mono) !important; }
[class*="theme-"].sf-enforce :is(.bg-card, [class*="card"]) {
  box-shadow: var(--shadow-2) !important;
  border-radius: var(--radius-lg) !important;
  border: var(--border-width) solid var(--line) !important;
}
[class*="theme-"].sf-enforce :is([class*="shadow-sm"], [class*="shadow-md"]) { box-shadow: var(--shadow-1) !important; }
[class*="theme-"].sf-enforce :is([class*="shadow-lg"], [class*="shadow-xl"]) { box-shadow: var(--shadow-3) !important; }
